mapper.select:
SELECT s.song_id FROM songs_tbl s JOIN song_genre_tbl sg ON s.song_id = sg.song_id JOIN (
SELECT #{ks.genreId} AS genre_id, #{ks.totalScore} AS kw_score FROM DUAL
) kw ON sg.genre_id = kw.genre_id GROUP BY s.song_id ORDER BY SUM(kw.kw_score) DESC FETCH FIRST #{amount} ROWS ONLY

SELECT s.song_id FROM songs_tbl s JOIN song_genre_tbl sg ON s.song_id = sg.song_id JOIN (
SELECT #{kw.genreId} AS genre_id FROM dual
) tk ON sg.genre_id = tk.genre_id LEFT JOIN song_score_tbl ss ON s.song_id = ss.song_id GROUP BY s.song_id ORDER BY NVL(SUM(ss.score), 0) DESC FETCH FIRST #{amount} ROWS ONLY

SELECT s.song_id FROM songs_tbl s JOIN albums_tbl a ON s.album_id = a.album_id JOIN song_genre_tbl sg ON s.song_id = sg.song_id JOIN (
SELECT #{kw.genreId} AS genre_id FROM dual
) tk ON sg.genre_id = tk.genre_id GROUP BY s.song_id, a.release_date ORDER BY a.release_date DESC FETCH FIRST #{amount} ROWS ONLY

SELECT s.song_id AS songId, ar.name AS artistName, s.title AS title, al.cover_image_url AS coverImageUrl FROM songs_tbl s JOIN artists_tbl ar ON s.artist_id = ar.artist_id JOIN albums_tbl al ON s.album_id = al.album_id WHERE s.song_id IN
#{id}
ORDER BY s.song_id DESC
